from test_bufftap import test, ROOT

B = 'local B=BuffTap; '
GROUP = B + '''
B.db.groupRequests=true; B.db.nearbyEnabled=false; B.db.nearbyRequests=false; B.db.group=false
IsInGroup=function() return true end; IsInRaid=function() return false end
GetNumSubgroupMembers=function() return 2 end
local oldClass=UnitClass; UnitClass=function(u) if u=='party1' then return 'Priest','PRIEST' end return oldClass(u) end
local sent=0; SendChatMessage=function(text,kind,language,name) sent=sent+1; lastMessage=text; lastName=name end
local entry={unit='party1',guid=UnitGUID('party1'),class='PRIEST'}
'''

test('Group requests start off and do not depend on group buffing', GROUP + "B.db.groupRequests=false; assert(not B:RequestableBuffs(entry,'group')); B.db.groupRequests=true; assert(B:RequestBuffFrom(entry,'group') and sent==1)")
test('Group requests send exactly one explicit whisper with shared text', GROUP + "B.db.requestMessage='Please %s'; assert(sent==0); assert(B:RequestBuffFrom(entry,'group')); assert(sent==1 and lastMessage:find('Please ',1,true)); assert(not B:RequestBuffFrom(entry,'group') and sent==1)")
test('Already covered buffs cannot be requested from group', GROUP + "aura('player',1243,'Power Word: Fortitude'); aura('player',14752,'Divine Spirit'); aura('player',976,'Shadow Protection'); B:InvalidateAura('player'); assert(not B:RequestableBuffs(entry,'group') and not B:RequestBuffFrom(entry,'group') and sent==0)")
test('Receiving buffs before sending prevents stale group whisper', GROUP + "assert(B:RequestableBuffs(entry,'group')); aura('player',1243,'Power Word: Fortitude'); aura('player',14752,'Divine Spirit'); aura('player',976,'Shadow Protection'); B.events.scripts.OnEvent(nil,'UNIT_AURA','player'); assert(not B:RequestBuffFrom(entry,'group') and sent==0)")
test('Changed group recipient GUID cannot receive stale request', GROUP + "local old=UnitGUID; UnitGUID=function(u) return u=='party1' and 'Other' or old(u) end; assert(not B:RequestBuffFrom(entry,'group') and sent==0)")
for block in ["combat=true", "B.db.groupRequests=false", "IsInGroup=function() return false end", "IsInRaid=function() return nil end", "UnitIsConnected=function() return false end", "UnitIsDeadOrGhost=function() return true end", "GetNumSubgroupMembers=function() return 0 end", "GetNumSubgroupMembers=function() return 99 end"]:
    test('Group request blocks unsafe or disabled recipient: '+block, GROUP + block + "; assert(not B:RequestBuffFrom(entry,'group') and sent==0)")
test('Group requests honor chat lockdown and native refusal', GROUP + "C_ChatInfo={InChatMessagingLockdown=function() return true end}; assert(not B:RequestBuffFrom(entry,'group') and sent==0); C_ChatInfo.InChatMessagingLockdown=function() return false end; SendChatMessage=function() return false end; assert(not B:RequestBuffFrom(entry,'group') and not B:RequestCooling(entry))")
test('Raid requests use current raid membership', GROUP + "IsInRaid=function() return true end; GetNumGroupMembers=function() return 2 end; local exists=UnitExists; UnitExists=function(u) return u=='raid1' or exists(u) end; local guid=UnitGUID; UnitGUID=function(u) return u=='raid1' and entry.guid or guid(u) end; local class=UnitClass; UnitClass=function(u) if u=='raid1' then return 'Priest','PRIEST' end return class(u) end; assert(B:RequestBuffFrom(entry,'group') and sent==1)")
test('Shared choices can be configured group-only without a separate name picker', GROUP + "B:Options(); B:UpdateHelperOptions(); local f=B.helperWindow; assert(f.groupRequestEnable:GetChecked() and not f.groupRequestPick and f.groupRequestsOpen); for _,c in pairs(f.requestChecks) do assert(c.enabled~=false) end; assert(not B.db.nearbyRequests)")

FOOD = B + "stock(250071,1248401); consumables('food'); B.db.consumablesInstanceOnly=true; B:SetSituationValue('solo','consumables','consumableLocations','everywhere','food'); IsInInstance=function() return false,'none' end; "
test('Food remains available outdoors while flask follows old instance-only default', FOOD + "stock(13510,17626); B.db.consumableFamilies.flask=true; refresh(); assert(B.action and B.action.familyKey=='food'); assert(B:CategoryRestingPause('consumables',B:ConsumableFamily('flask'))); assert(not B:CategoryRestingPause('consumables',B:ConsumableFamily('food')))")
test('Everywhere food still obeys resting pause', FOOD + "B.db.consumablesPauseResting=true; IsResting=function() return true end; refresh(); assert(not (B.action and B.action.source=='consumable'))")
test('Consumable location is rechecked at click after instance exit', B + "stock(250071,1248401); consumables('food'); B:SetSituationValue('solo','consumables','consumableLocations','instances','food'); local inside=true; IsInInstance=function() return inside,inside and 'party' or 'none' end; refresh(); assert(B.action); inside=false; B.button.scripts.PreClick(B.button,'LeftButton',true); assert(not B.action and not B.button.attrs.type1)")
test('Manual consumables honor individual location rules', FOOD + "UnitInVehicle=function() return false end; B:SetConsumableMode(B:ConsumableFamily('food'),'manual'); B:UpdateManualConsumables(); assert(#B.manualConsumableEntries==1,'outdoor manual '..tostring(#B.manualConsumableEntries)..' mode '..B:ConsumableMode(B:ConsumableFamily('food'))..' where '..B:ConsumableLocation(B:ConsumableFamily('food')));  B:SetSituationValue('solo','consumables','consumableLocations','instances','food'); B:UpdateManualConsumables(); assert(#B.manualConsumableEntries==0,'blocked entries '..tostring(#B.manualConsumableEntries))")
test('Hidden elixir children inherit the visible parent location', B + "B:SetSituationValue('solo','consumables','consumableLocations','instances','ferocity'); local parent=B:ConsumableFamily('ferocity'); assert(parent and parent.multi); local child=parent.children[1]; assert(B:ConsumableLocation(child)=='instances'); B:SetSituationValue('solo','consumables','consumableLocations','everywhere','ferocity'); assert(B:ConsumableLocation(child)=='everywhere')")
test('Per-category location is saved for Party and reset through Use Solo settings', B + "assert(B:SetSituationValue('party','consumables','consumableLocations','instances','food')); local settings=B:SituationPreview('party','consumables'); assert(B:ConsumableLocation(B:ConsumableFamily('food'),settings)=='instances'); B:CustomizeSituation('party','consumables',false); assert(B:ConsumableLocation(B:ConsumableFamily('food'),B:SituationPreview('party','consumables'))=='everywhere')")
test('Per-category location routes to independent spec settings', B + "GetNumSpecGroups=function() return 2 end; C_SpecializationInfo={GetActiveSpecGroup=function() return 1 end}; B:SetSpecEnabled(true); B:SetEditSpec(2); assert(B:SetSituationValue('solo','consumables','consumableLocations','instances','food')); assert(B:ConsumableLocation(B:ConsumableFamily('food'),B:SituationPreview('solo','consumables',2))=='instances'); assert(B:ConsumableLocation(B:ConsumableFamily('food'),B:SituationPreview('solo','consumables',1))=='everywhere')")
test('Consumable row exposes a usable location selector even while family off', B + "B:Options(); local row=B.options.consumableRows[1]; assert(row.location); row.location.scripts.OnClick(row.location); assert(row.location.menu.shown); row.location.menu.rows[2].scripts.OnClick(row.location.menu.rows[2]); assert(B:ConsumableLocation(row.family,B:EditorSettings('consumables'))=='instances')")

test('Carried bag enumeration includes extra equipped slot without banks', B + "NUM_BAG_SLOTS=4; NUM_TOTAL_EQUIPPED_BAG_SLOTS=5; Enum.BagIndex={ReagentBag=5,Bank=-1,Reagentbank=-3}; local ids=B.API.CarriedBagIDs(); assert(#ids==6 and ids[1]==0 and ids[6]==5)")
test('Malformed extra bag indices never add bank or unbounded slots', B + "NUM_BAG_SLOTS=4; NUM_TOTAL_EQUIPPED_BAG_SLOTS=999; Enum.BagIndex={ReagentBag=-3}; local ids=B.API.CarriedBagIDs(); assert(#ids==5 and ids[5]==4)")
test('Discovery scans consumables in the extra carried bag', B + "B.db.helperDiscovery=true; NUM_BAG_SLOTS=4; Enum.BagIndex={ReagentBag=5}; C_Container={GetContainerNumSlots=function(b) return b==5 and 1 or 0 end,GetContainerItemID=function(b,s) return b==5 and 999001 end}; C_Item.GetItemInfo=function() return {itemName='Unlisted',classID=0} end; B:DiscoverConsumables(); assert(#B.helperDiscoveries==1 and B.helperDiscoveries[1].id==999001)")
test('Camp setup can find an unlocked item in the extra carried bag', B + "NUM_BAG_SLOTS=4; Enum.BagIndex={ReagentBag=5}; C_Container={GetContainerNumSlots=function(b) return b==5 and 1 or 0 end,GetContainerItemInfo=function(b,s) return {itemID=999001,isLocked=false} end}; local bag,slot=B:CampBagSlot(999001); assert(bag==5 and slot==1)")
test('Healthstone scan includes extra bag but special-bag free slots do not permit creation', B + "NUM_BAG_SLOTS=4; Enum.BagIndex={ReagentBag=5}; local seen=false; C_Item.GetItemCount=function() return 0 end; C_Container={GetContainerNumSlots=function(b) return b==0 and 16 or b==5 and 1 or 0 end,GetContainerNumFreeSlots=function(b) return b==5 and 1 or 0,b==5 and 4 or 0 end,GetContainerItemID=function(b,s) if b==5 then seen=true end return nil end,GetContainerItemInfo=function() return nil end}; B.readinessInventory=nil; local state=B:HealthstoneInventory(); assert(seen and state.hasStone==false and state.capacity==false)")
test('Supply totals use the item-count API including extra carried storage', B + "C_Item.GetItemCount=function(id,bank) assert(not bank); return id==6265 and 7 or 0 end; B.supplyCounts=nil; assert(B:SupplyCount(6265)==7)")
test('Location map drops invalid enums without changing legacy instance rule', B + "B.db.consumablesInstanceOnly=true; B.db.consumableLocations={food='bad',unknown='everywhere'}; B:InitDB(); assert(not next(B.db.consumableLocations)); assert(B:ConsumableLocation(B:ConsumableFamily('food'))=='instances')")
test('Paladin group requests do not ask for a second blessing', GROUP + "UnitClass=function(u) return u=='party1' and 'Paladin' or 'Druid',u=='party1' and 'PALADIN' or 'DRUID' end; entry.class='PALADIN'; aura('player',19740,'Blessing of Might'); B:InvalidateAura('player'); assert(not B:RequestableBuffs(entry,'group') and not B:RequestBuffFrom(entry,'group') and sent==0)")
test('Group requests can ask a different player of the same class', GROUP + "entry.class='DRUID'; UnitClass=function() return 'Druid','DRUID' end; assert(B:RequestBuffFrom(entry,'group') and sent==1)")
test('Maintenance diagnostic reports missing cooldown without authorizing it', B + "spell(2782,'Remove Curse'); C_Spell.GetSpellCooldown=function() return nil end; local lines=table.concat(B:MaintenanceProbeLines(),'\\n'); assert(lines:find('cooldown=nil',1,true) and lines:find('maintenance ready=false',1,true))")
test('Maintenance diagnostic avoids cooldown probes in combat', B + "spell(2782,'Remove Curse'); combat=true; C_Spell.GetSpellCooldown=function() error('must not probe') end; local lines=table.concat(B:MaintenanceProbeLines(),'\\n'); assert(lines:find('checked after combat',1,true))")
for item, use in [(287973,1248395),(287974,1249522)]:
    test('New verified food variant creates exact food action '+str(item), B + f"stock({item},{use}); consumables('food'); B.db.consumableChoices.food={item}; refresh(); assert(B.action and B.action.itemID=={item})")

from test_nearby import setup as NEARBY
ROWS = NEARBY + """
local B=BuffTap; B.db.groupRequests=true; B.db.nearbyRequests=false; B.db.nearbyProviderSort=false
B.db.nearbyShowAll=false; B.db.nearbyBuffing=false; B.db.group=false
IsInGroup=function() return true end; IsInRaid=function() return false end; GetNumSubgroupMembers=function() return 1 end
local guid=UnitGUID; UnitGUID=function(u) return u=='nameplate1' and guid('party1') or guid(u) end
local class=UnitClass; UnitClass=function(u) if u=='party1' or u=='nameplate1' then return 'Priest','PRIEST' end return class(u) end
UnitInParty=function(u) return u=='party1' or u=='nameplate1' end
local sent=0; SendChatMessage=function() sent=sent+1 end
now=now+.1; B.nearbyDisplay={}; B.nearbySnapshot=nil; B.nearbyNeedCache={}; B:SeedNearby(); refresh(); B:UpdateNearbyWindow()
"""
test('Party member gets the existing request icon in Nearby with both buffing and provider sort off', ROWS + "local row=B.nearbyFrame.rows[1]; assert(row.entry and row.entry.guid==UnitGUID('party1') and row.request.shown and sent==0); row.request.scripts.OnClick(row.request); assert(sent==1 and B:RequestCooling(row.entry)); row.request.scripts.OnClick(row.request); assert(sent==1)")
test('Receiving buffs after row appeared prevents the Nearby group request', ROWS + "local row=B.nearbyFrame.rows[1]; assert(row.request.shown); aura('player',1243,'Power Word: Fortitude'); aura('player',14752,'Divine Spirit'); aura('player',976,'Shadow Protection'); B.events.scripts.OnEvent(nil,'UNIT_AURA','player'); row.request.scripts.OnClick(row.request); assert(sent==0); B:UpdateNearbyWindow(); assert(not row.request.shown)")
test('Leaving group before row click blocks the request', ROWS + "local row=B.nearbyFrame.rows[1]; IsInGroup=function() return false end; row.request.scripts.OnClick(row.request); assert(sent==0)")
test('Turning group requests off removes provider-only group row', ROWS + "B.db.groupRequests=false; B:UpdateNearbyWindow(); assert(not B.nearbyFrame.rows[1].request.shown and sent==0)")
test('Recycled nameplate cannot send a stale group request', ROWS + "local row=B.nearbyFrame.rows[1]; local previous=UnitGUID; UnitGUID=function(u) return u=='nameplate1' and 'Player-Recycled' or previous(u) end; row.request.scripts.OnClick(row.request); assert(sent==0)")
test('Raid members get request icons in the same Nearby rows', ROWS + "IsInRaid=function() return true end; GetNumGroupMembers=function() return 1 end; local exists=UnitExists; UnitExists=function(u) return u=='raid1' or exists(u) end; local previous=UnitGUID; UnitGUID=function(u) return u=='raid1' and previous('party1') or previous(u) end; local previousClass=UnitClass; UnitClass=function(u) if u=='raid1' then return 'Priest','PRIEST' end return previousClass(u) end; now=now+.1; B:UpdateNearbyWindow(); local row=B.nearbyFrame.rows[1]; assert(row.request.shown); row.request.scripts.OnClick(row.request); assert(sent==1)")
test('Open window shortcut enables Nearby without enabling outsider requests', GROUP + "B:OpenNearbyForRequests(); assert(B.db.nearbyEnabled and not B.db.nearbyRequests and sent==0)")
